`timescale 1ps/1ps
// tb_bp_seq.sv (brief 96F1): the buffer-bypass START-UP SEQUENCE, with AMD's own controllers. The Wizard's auto-mode controllers (gtwizard_ultrascale_v1_7_23_gtwiz_buffbypass_tx and _rx, as generated by
// ip/amd_ip_bypass.tcl, compiled from the generated sources, NOT committed) are instantiated beside our gt_bp_gate. The transceiver itself is a STAND-IN: after TXDLYSRESET (RXDLYSRESET) it drops
// SYNCDONE and PHALIGNDONE and raises them again after SYNC_CLKS clocks (the real latency is not in any document read: UNCONFIRMED; the test uses several values), or never raises PHALIGNDONE (the error case).
// It checks the controllers' behaviour as read from their source, and the need for and the effect of the gate:
//  1. start on the rising edge of the reset-done input; done rises after the stand-in's SYNCDONE; error low when PHALIGNDONE is high;
//  2. after a datapath reset (reset-done low then high again) the PREVIOUS done is still high for a few clocks: `stale` counts those clocks (the gate must hold run low through them);
//  3. run is never high before the controller has restarted and finished; run stays low when the controller flags an error (PHALIGNDONE low) until the next reset-done rising edge;
//  4. the controller's clock-inactive reset (our reset_in = not user-clock-active) clears done and error.
// Both directions are the same source with different names; the bench instantiates the TX one and the RX one on clocks that differ by 1.7 ps/ns (unrelated clocks).
module tb_bp_seq;
    int SYNC_CLKS = 100;
    logic txclk = 0, rxclk = 0;
    always #3103 txclk = ~txclk;          // 161.13 MHz
    always #3100 rxclk = ~rxclk;
    // ---------------- TX side
    logic t_rstdone = 0, t_rst = 1, t_phdone = 1, t_syncdone = 1, t_done, t_err, t_run;
    logic [0:0] t_dlysreset;
    gtwizard_ultrascale_v1_7_23_gtwiz_buffbypass_tx #(.P_BUFFER_BYPASS_MODE(0), .P_TOTAL_NUMBER_OF_CHANNELS(1), .P_MASTER_CHANNEL_POINTER(0)) u_tx (
        .gtwiz_buffbypass_tx_clk_in(txclk), .gtwiz_buffbypass_tx_reset_in(t_rst), .gtwiz_buffbypass_tx_start_user_in(1'b0), .gtwiz_buffbypass_tx_resetdone_in(t_rstdone),
        .gtwiz_buffbypass_tx_done_out(t_done), .gtwiz_buffbypass_tx_error_out(t_err),
        .txphaligndone_in(t_phdone), .txphinitdone_in(1'b0), .txdlysresetdone_in(1'b0), .txsyncout_in(1'b0), .txsyncdone_in(t_syncdone),
        .txphdlyreset_out(), .txphalign_out(), .txphalignen_out(), .txphdlypd_out(), .txphinit_out(), .txphovrden_out(), .txdlysreset_out(t_dlysreset), .txdlybypass_out(),
        .txdlyen_out(), .txdlyovrden_out(), .txphdlytstclk_out(), .txdlyhold_out(), .txdlyupdown_out(), .txsyncmode_out(), .txsyncallin_out(), .txsyncin_out());
    gt_bp_gate u_gt (.clk(txclk), .rst_done(t_rstdone), .bp_done(t_done), .bp_err(t_err), .run(t_run));
    // ---------------- RX side
    logic r_rstdone = 0, r_rst = 1, r_phdone = 1, r_syncdone = 1, r_done, r_err, r_run;
    logic [0:0] r_dlysreset;
    gtwizard_ultrascale_v1_7_23_gtwiz_buffbypass_rx #(.P_BUFFER_BYPASS_MODE(0), .P_TOTAL_NUMBER_OF_CHANNELS(1), .P_MASTER_CHANNEL_POINTER(0)) u_rx (
        .gtwiz_buffbypass_rx_clk_in(rxclk), .gtwiz_buffbypass_rx_reset_in(r_rst), .gtwiz_buffbypass_rx_start_user_in(1'b0), .gtwiz_buffbypass_rx_resetdone_in(r_rstdone),
        .gtwiz_buffbypass_rx_done_out(r_done), .gtwiz_buffbypass_rx_error_out(r_err),
        .rxphaligndone_in(r_phdone), .rxdlysresetdone_in(1'b0), .rxsyncout_in(1'b0), .rxsyncdone_in(r_syncdone),
        .rxphdlyreset_out(), .rxphalign_out(), .rxphalignen_out(), .rxphdlypd_out(), .rxphovrden_out(), .rxdlysreset_out(r_dlysreset), .rxdlybypass_out(),
        .rxdlyen_out(), .rxdlyovrden_out(), .rxsyncmode_out(), .rxsyncallin_out(), .rxsyncin_out());
    gt_bp_gate u_gr (.clk(rxclk), .rst_done(r_rstdone), .bp_done(r_done), .bp_err(r_err), .run(r_run));
    // ---------------- transceiver stand-in
    logic t_err_mode = 0, r_err_mode = 0;      // 1: PHALIGNDONE never rises
    always @(posedge t_dlysreset) begin
        t_syncdone <= 1'b0; t_phdone <= 1'b0;
        repeat (SYNC_CLKS) @(posedge txclk);
        t_syncdone <= 1'b1; t_phdone <= !t_err_mode;
    end
    always @(posedge r_dlysreset) begin
        r_syncdone <= 1'b0; r_phdone <= 1'b0;
        repeat (SYNC_CLKS) @(posedge rxclk);
        r_syncdone <= 1'b1; r_phdone <= !r_err_mode;
    end
    // ---------------- checks
    int errors = 0, checks = 0;
    int t_stale = 0, r_stale = 0, t_early_run = 0, r_early_run = 0, t_naive_early = 0, r_naive_early = 0;
    logic t_restarted = 0, r_restarted = 0;      // the controller dropped done after the reset-done edge (a new sequence started)
    always @(posedge txclk) begin
        if (!t_rstdone) t_restarted <= 0; else if (!t_done) t_restarted <= 1;
        if (t_rstdone && t_done && !t_restarted) t_stale++;                    // done high from the PREVIOUS sequence
        if (t_run && !(t_rstdone && t_done && t_restarted && !t_err)) t_early_run++;   // the gate released without a finished current sequence
        if (t_rstdone && t_done && !t_restarted) t_naive_early++;
    end
    always @(posedge rxclk) begin
        if (!r_rstdone) r_restarted <= 0; else if (!r_done) r_restarted <= 1;
        if (r_rstdone && r_done && !r_restarted) r_stale++;
        if (r_run && !(r_rstdone && r_done && r_restarted && !r_err)) r_early_run++;
        if (r_rstdone && r_done && !r_restarted) r_naive_early++;
    end
    task automatic check(input string what, input bit ok);
        checks++;
        if (!ok) begin errors++; $display("FAIL: %s (t=%0t)", what, $time); end else $display("ok:   %s", what);
    endtask
    task automatic bring_up(input int sync_clks, input bit tx_err, input bit rx_err);
        SYNC_CLKS = sync_clks; t_err_mode = tx_err; r_err_mode = rx_err;
        @(posedge txclk); t_rstdone <= 1'b1; @(posedge rxclk); r_rstdone <= 1'b1;      // the reset helpers finish: the controllers must start by themselves
        repeat (sync_clks + 40) @(posedge txclk);
    endtask
    task automatic datapath_reset();
        @(posedge txclk); t_rstdone <= 1'b0; @(posedge rxclk); r_rstdone <= 1'b0;
        repeat (20) @(posedge txclk);
    endtask
    initial begin
        int sc;
        repeat (10) @(posedge txclk);
        t_rst <= 0; r_rst <= 0;                         // the user clocks are active: the controllers are out of reset
        repeat (10) @(posedge txclk);
        for (int k = 0; k < 4; k++) begin
            sc = (k == 0) ? 20 : (k == 1) ? 100 : (k == 2) ? 400 : 3;
            t_stale = 0; r_stale = 0; t_early_run = 0; r_early_run = 0; t_naive_early = 0; r_naive_early = 0;
            bring_up(sc, 0, 0);
            check($sformatf("SYNC_CLKS=%0d TX: done, no error, run", sc), t_done && !t_err && t_run);
            check($sformatf("SYNC_CLKS=%0d RX: done, no error, run", sc), r_done && !r_err && r_run);
            check($sformatf("SYNC_CLKS=%0d run never released early (TX %0d, RX %0d clocks)", sc, t_early_run, r_early_run), t_early_run == 0 && r_early_run == 0);
            datapath_reset();
            check("run drops with the reset helper's done", !t_run && !r_run);
            bring_up(sc, 0, 0);
            $display("INFO: SYNC_CLKS=%0d after the 2nd reset-done edge: done was still high from the previous sequence for TX %0d, RX %0d clocks (the gate held run low through them)", sc, t_stale, r_stale);
            check($sformatf("SYNC_CLKS=%0d second sequence: done, run, never early (TX %0d RX %0d)", sc, t_early_run, r_early_run), t_done && r_done && t_run && r_run && t_early_run == 0 && r_early_run == 0);
            check("the stale-done window exists (the gate is needed)", t_stale > 0 && r_stale > 0);
            datapath_reset();
        end
        // error case: PHALIGNDONE never high
        t_early_run = 0; r_early_run = 0;
        bring_up(50, 1, 1);
        check("error case: done and error both high", t_done && t_err && r_done && r_err);
        check("error case: run stays low", !t_run && !r_run && t_early_run == 0 && r_early_run == 0);
        datapath_reset();
        bring_up(50, 0, 0);
        check("error clears at the next sequence and run is back", t_done && !t_err && r_done && !r_err && t_run && r_run);
        // clock-inactive reset clears done and error
        @(posedge txclk); t_rst <= 1; @(posedge rxclk); r_rst <= 1; repeat (4) @(posedge txclk);
        check("reset_in clears done and error", !t_done && !t_err && !r_done && !r_err && !t_run && !r_run);
        $display("%s: %0d checks, %0d failed", errors == 0 ? "PASS" : "FAIL", checks, errors);
        $finish;
    end
endmodule
